'use client';

import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { cn } from '@/registry/ndeko/lib/utils';

import {
  MONEY_FORMAT,
  MONEY_LOCALE,
  daysLabelOf,
  formatWholeMoney,
  onDemandTotal,
  type SpendCap,
} from './billing-model';
import { INITIAL_CAP, PLAN } from './data';
import { SpendCapCard } from './spend-cap';
import { UsageMeters } from './usage-meters';

const CARD_SURFACE =
  'bg-card hairline-ring ring-border rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.03]';

/** What the next invoice adds on top of the plan: everything spent, or the cap when it is lower. */
function chargedOnDemandOf(cap: SpendCap, spent: number) {
  if (!cap.isCapped) {
    return spent;
  }
  return Math.min(spent, cap.amount);
}

export default function Billing01() {
  const [cap, setCap] = useState<SpendCap>(INITIAL_CAP);
  const spent = onDemandTotal();
  const chargedOnDemand = chargedOnDemandOf(cap, spent);
  const estimate = PLAN.monthlyPrice + chargedOnDemand;
  const planPrice = formatWholeMoney(PLAN.monthlyPrice);
  const resetsIn = daysLabelOf(PLAN.resetsInDays);

  return (
    <div className='bg-background text-foreground min-h-dvh w-full'>
      <div className='mx-auto flex w-full max-w-3xl flex-col gap-4 px-4 py-6 md:px-6 md:py-10'>
        <header className='flex flex-col gap-1'>
          <p className='text-muted-foreground text-xs'>{PLAN.workspace}</p>
          <h1 className='text-lg font-semibold text-balance'>
            Usage and billing
          </h1>
        </header>
        <section
          aria-label='Next invoice'
          className={cn(
            CARD_SURFACE,
            'flex flex-wrap items-end justify-between gap-x-6 gap-y-3 p-4 sm:p-5'
          )}
        >
          <div className='flex flex-col gap-1'>
            <p className='text-muted-foreground text-xs'>
              Next invoice, {PLAN.renewsOn}
            </p>
            <MotionNumber
              value={estimate}
              locale={MONEY_LOCALE}
              format={MONEY_FORMAT}
              className='text-2xl leading-8 font-semibold'
            />
            <p className='text-muted-foreground text-xs tabular-nums'>
              {PLAN.name} {planPrice}, on demand{' '}
              <MotionNumber
                value={chargedOnDemand}
                locale={MONEY_LOCALE}
                format={MONEY_FORMAT}
              />
            </p>
          </div>
          <p className='text-muted-foreground text-xs'>
            Usage resets in {resetsIn} · Illustrative figures
          </p>
        </section>
        <section
          aria-labelledby='billing-01-usage'
          className={cn(CARD_SURFACE, 'flex flex-col gap-5 p-4 sm:p-5')}
        >
          <h2 id='billing-01-usage' className='text-sm font-medium'>
            This month
          </h2>
          <UsageMeters />
        </section>
        <section
          aria-label='On-demand spending'
          className={cn(CARD_SURFACE, 'p-4 sm:p-5')}
        >
          <SpendCapCard cap={cap} spent={spent} onCapChange={setCap} />
        </section>
      </div>
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type MotionProps,
  type Transition,
} from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll, type WordRollWord } from '@/components/core/word-roll';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Slider, SliderThumbValue } from '@/registry/ndeko/ui/slider';
import { Switch } from '@/registry/ndeko/ui/switch';

import {
  MONEY_FORMAT,
  MONEY_LOCALE,
  WHOLE_MONEY_FORMAT,
  formatWholeMoney,
  isCapReached,
  sameCap,
  shareOfCapRange,
  type SpendCap,
} from './billing-model';
import { CAP_BOUNDS, PLAN } from './data';
import { SaveButton, type SaveStatus } from './save-button';

const SAVING_MS = 700;

const SAVED_HOLD_MS = 900;

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.14, ease: EASE_OUT_STRONG };

type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

function delayOf(status: SaveStatus) {
  if (status === 'saving') {
    return SAVING_MS;
  }
  return SAVED_HOLD_MS;
}

function amountOf(value: number | readonly number[]) {
  if (typeof value === 'number') {
    return value;
  }
  return value[0];
}

function capAriaTextOf(_formatted: string, value: number) {
  return `${formatWholeMoney(value)} a month`;
}

function fillToneOf(isReached: boolean) {
  if (isReached) {
    return 'bg-warning';
  }
  return 'bg-primary';
}

function markerOpacityOf(isCapped: boolean) {
  if (isCapped) {
    return 'opacity-100';
  }
  return 'opacity-0';
}

type SpendBarProps = {
  spent: number;
  cap: SpendCap;
};

/** Spending so far against the whole range of caps, with a marker where the cap sits. */
function SpendBar({ spent, cap }: SpendBarProps) {
  const isReached = isCapReached(cap, spent);
  const spentShare = shareOfCapRange(spent);
  const capShare = shareOfCapRange(cap.amount);
  const fillStyle = { transform: `scaleX(${spentShare})` };
  const capPercent = capShare * 100;
  const markerTrackStyle = { transform: `translateX(${capPercent}%)` };

  return (
    <div aria-hidden='true' className='relative py-1'>
      <div className='bg-foreground/10 h-1.5 overflow-hidden rounded-full'>
        <span
          style={fillStyle}
          className={cn(
            'block h-full origin-left rounded-full transition-colors duration-150 rtl:origin-right',
            fillToneOf(isReached)
          )}
        />
      </div>
      <span
        style={markerTrackStyle}
        className='pointer-events-none absolute inset-0 transition-transform duration-150 ease-(--ease-out-strong) rtl:-scale-x-100'
      >
        <span
          className={cn(
            'bg-foreground absolute top-0 left-0 h-3.5 w-0.5 -translate-x-1/2 rounded-full transition-opacity duration-150',
            markerOpacityOf(cap.isCapped)
          )}
        />
      </span>
    </div>
  );
}

type CapEditorProps = {
  draft: SpendCap;
  status: SaveStatus;
  hasChanges: boolean;
  onDraftChange: (draft: SpendCap) => void;
  onCancel: () => void;
  onSave: () => void;
};

function CapEditor({
  draft,
  status,
  hasChanges,
  onDraftChange,
  onCancel,
  onSave,
}: CapEditorProps) {
  const isBusy = status !== 'idle';
  const isSliderOff = !draft.isCapped;

  function changeAmount(value: number | readonly number[]) {
    const amount = amountOf(value);
    onDraftChange({ ...draft, amount });
  }

  function changeCapped(isCapped: boolean) {
    onDraftChange({ ...draft, isCapped });
  }

  return (
    <div className='flex flex-col gap-4 pt-5'>
      <label className='flex cursor-pointer items-center justify-between gap-3 text-[13px]'>
        Stop on-demand charges at a monthly cap
        <Switch checked={draft.isCapped} onCheckedChange={changeCapped} />
      </label>
      <div className='flex flex-col gap-1'>
        <Slider
          value={draft.amount}
          min={CAP_BOUNDS.min}
          max={CAP_BOUNDS.max}
          step={CAP_BOUNDS.step}
          disabled={isSliderOff}
          thumbLabels={['Monthly cap']}
          getAriaValueText={capAriaTextOf}
          thumbContent={() => (
            <SliderThumbValue>
              {formatWholeMoney(draft.amount)}
            </SliderThumbValue>
          )}
          onValueChange={changeAmount}
        />
        <div className='text-muted-foreground flex justify-between text-xs tabular-nums'>
          <span>{formatWholeMoney(CAP_BOUNDS.min)}</span>
          <span>{formatWholeMoney(CAP_BOUNDS.max)}</span>
        </div>
      </div>
      <div className='flex items-center justify-end gap-2'>
        <Button variant='ghost' disabled={isBusy} onClick={onCancel}>
          Cancel
        </Button>
        <SaveButton
          status={status}
          idleLabel='Save cap'
          disabled={!hasChanges}
          onSave={onSave}
        />
      </div>
    </div>
  );
}

type CapFigureProps = {
  cap: SpendCap;
};

const NO_CAP_WORD: WordRollWord = {
  key: 'no-cap',
  text: 'No cap',
  node: <span className='font-medium'>No cap</span>,
};

/** The amount keeps its slot while it changes, so a new cap rolls its digits and only a switch rolls the words. */
function capWordsOf(cap: SpendCap): WordRollWord[] {
  if (!cap.isCapped) {
    return [NO_CAP_WORD];
  }
  const amount: WordRollWord = {
    key: 'amount',
    text: formatWholeMoney(cap.amount),
    node: (
      <MotionNumber
        value={cap.amount}
        locale={MONEY_LOCALE}
        format={WHOLE_MONEY_FORMAT}
        className='font-medium'
      />
    ),
  };
  return [amount, 'a', 'month'];
}

function CapFigure({ cap }: CapFigureProps) {
  const words = capWordsOf(cap);
  return <WordRoll words={words} />;
}

function shownCapOf(isEditing: boolean, draft: SpendCap, cap: SpendCap) {
  if (isEditing) {
    return draft;
  }
  return cap;
}

type SpendCapCardProps = {
  cap: SpendCap;
  spent: number;
  onCapChange: (cap: SpendCap) => void;
};

export function SpendCapCard({ cap, spent, onCapChange }: SpendCapCardProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [draft, setDraft] = useState<SpendCap>(cap);
  const [status, setStatus] = useState<SaveStatus>('idle');
  const changeButtonRef = useRef<HTMLButtonElement>(null);
  const editorRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const heightPresence = heightPresenceOf(shouldReduceMotion);
  const shownCap = shownCapOf(isEditing, draft, cap);
  const isReached = isCapReached(shownCap, spent);
  const hasChanges = !sameCap(draft, cap);

  useEffect(() => {
    if (status === 'idle') {
      return;
    }
    function advance() {
      if (status === 'saving') {
        onCapChange(draft);
        setStatus('saved');
        return;
      }
      setStatus('idle');
      setIsEditing(false);
      window.requestAnimationFrame(() => changeButtonRef.current?.focus());
    }
    const delay = delayOf(status);
    const timer = window.setTimeout(advance, delay);
    return () => window.clearTimeout(timer);
  }, [status, draft, onCapChange]);

  function startEditing() {
    setDraft(cap);
    setIsEditing(true);
    window.requestAnimationFrame(() => {
      const firstControl =
        editorRef.current?.querySelector<HTMLElement>('button, input');
      firstControl?.focus();
    });
  }

  function cancel() {
    setIsEditing(false);
    setDraft(cap);
    window.requestAnimationFrame(() => changeButtonRef.current?.focus());
  }

  function save() {
    setStatus('saving');
  }

  return (
    <div className='flex flex-col gap-4'>
      <div className='flex flex-wrap items-start justify-between gap-x-4 gap-y-2'>
        <div className='flex flex-col gap-0.5'>
          <h2 className='text-sm font-medium'>On-demand spending</h2>
          <p className='text-muted-foreground text-xs text-pretty'>
            Use beyond the plan, added to the invoice of {PLAN.renewsOn}
          </p>
        </div>
        <AnimatePresence initial={false}>
          {!isEditing && (
            <motion.div key='change' {...FADE_PRESENCE}>
              <Button
                ref={changeButtonRef}
                variant='outline'
                size='sm'
                onClick={startEditing}
              >
                Change cap
              </Button>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
      <SpendBar spent={spent} cap={shownCap} />
      <div className='flex flex-wrap justify-between gap-x-4 gap-y-1 text-[13px]'>
        <span className='text-muted-foreground'>
          <MotionNumber
            value={spent}
            locale={MONEY_LOCALE}
            format={MONEY_FORMAT}
            className='text-foreground font-medium'
          />{' '}
          spent so far
        </span>
        <span className='text-muted-foreground'>
          Cap: <CapFigure cap={cap} />
        </span>
      </div>
      <AnimatedSize>
        <AnimatePresence initial={false}>
          {isReached && (
            <motion.p
              key='reached'
              {...heightPresence}
              className='text-warning-foreground overflow-hidden text-xs text-pretty'
            >
              <span className='block pb-1'>
                The cap is at or below what is already spent. Runs over the plan
                and new guest viewers pause until {PLAN.renewsOn}.
              </span>
            </motion.p>
          )}
        </AnimatePresence>
        {isEditing && (
          <motion.div
            ref={editorRef}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1, transition: ENTER }}
          >
            <CapEditor
              draft={draft}
              status={status}
              hasChanges={hasChanges}
              onDraftChange={setDraft}
              onCancel={cancel}
              onSave={save}
            />
          </motion.div>
        )}
      </AnimatedSize>
    </div>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';

import {
  fillOf,
  formatMoney,
  formatQuantity,
  overageCostOf,
  overageOf,
  toneOf,
  type MeterTone,
} from './billing-model';
import { METERS, type Meter } from './data';

const FILL_TONE: Record<MeterTone, string> = {
  calm: 'bg-primary',
  near: 'bg-warning',
  over: 'bg-warning',
};

const NOTE_TONE: Record<MeterTone, string> = {
  calm: 'text-muted-foreground',
  near: 'text-warning-foreground',
  over: 'text-warning-foreground',
};

function noteOf(meter: Meter, tone: MeterTone) {
  if (tone === 'over') {
    const overage = overageOf(meter);
    const extra = formatQuantity(overage, meter.decimals);
    if (meter.overagePrice === null) {
      return `${extra} ${meter.unit} over the plan`;
    }
    const overageCost = overageCostOf(meter);
    const cost = formatMoney(overageCost);
    return `${extra} ${meter.unit} over the plan, ${cost} on demand`;
  }
  const left = meter.included - meter.used;
  const leftText = formatQuantity(left, meter.decimals);
  return `${leftText} ${meter.unit} left`;
}

function MeterRow({ meter }: { meter: Meter }) {
  const tone = toneOf(meter);
  const fill = fillOf(meter);
  const used = formatQuantity(meter.used, meter.decimals);
  const included = formatQuantity(meter.included, 0);
  const note = noteOf(meter, tone);
  const valueNow = Math.min(meter.used, meter.included);
  const fillStyle = { transform: `scaleX(${fill})` };

  return (
    <li className='flex flex-col gap-2'>
      <div className='flex items-baseline justify-between gap-3'>
        <span className='text-[13px] font-medium'>{meter.label}</span>
        <span className='text-[13px] tabular-nums'>
          {used}{' '}
          <span className='text-muted-foreground'>
            of {included} {meter.unit}
          </span>
        </span>
      </div>
      <div
        role='meter'
        aria-label={meter.label}
        aria-valuemin={0}
        aria-valuemax={meter.included}
        aria-valuenow={valueNow}
        aria-valuetext={`${used} of ${included} ${meter.unit}`}
        className='bg-foreground/10 h-1.5 overflow-hidden rounded-full'
      >
        <span
          style={fillStyle}
          className={cn(
            'block h-full origin-left rounded-full rtl:origin-right',
            FILL_TONE[tone]
          )}
        />
      </div>
      <p className={cn('text-xs tabular-nums', NOTE_TONE[tone])}>{note}</p>
    </li>
  );
}

export function UsageMeters() {
  return (
    <ul className='flex flex-col gap-5'>
      {METERS.map((meter) => (
        <MeterRow key={meter.id} meter={meter} />
      ))}
    </ul>
  );
}

import { CAP_BOUNDS, METERS, type Meter } from './data';

export type MeterTone = 'calm' | 'near' | 'over';

export type SpendCap = { amount: number; isCapped: boolean };

export const MONEY_LOCALE = 'en-IE';

export const MONEY_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'EUR',
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
};

export const WHOLE_MONEY_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'EUR',
  maximumFractionDigits: 0,
};

const MONEY = new Intl.NumberFormat(MONEY_LOCALE, MONEY_FORMAT);

const WHOLE_MONEY = new Intl.NumberFormat(MONEY_LOCALE, WHOLE_MONEY_FORMAT);

const NEAR_LIMIT_SHARE = 0.8;

export function formatMoney(amount: number) {
  return MONEY.format(amount);
}

export function formatWholeMoney(amount: number) {
  return WHOLE_MONEY.format(amount);
}

export function formatQuantity(value: number, decimals: number) {
  const formatter = new Intl.NumberFormat('en-US', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
  return formatter.format(value);
}

export function overageOf(meter: Meter) {
  const extra = meter.used - meter.included;
  return Math.max(extra, 0);
}

export function overageCostOf(meter: Meter) {
  if (meter.overagePrice === null) {
    return 0;
  }
  const extra = overageOf(meter);
  return extra * meter.overagePrice;
}

export function onDemandTotal() {
  let total = 0;
  for (const meter of METERS) {
    total += overageCostOf(meter);
  }
  return total;
}

export function toneOf(meter: Meter): MeterTone {
  const share = meter.used / meter.included;
  if (share > 1) {
    return 'over';
  }
  if (share >= NEAR_LIMIT_SHARE) {
    return 'near';
  }
  return 'calm';
}

/** The share of the bar to fill, never past its end: the overage is told in words beside it. */
export function fillOf(meter: Meter) {
  const share = meter.used / meter.included;
  return Math.min(share, 1);
}

export function shareOfCapRange(amount: number) {
  const span = CAP_BOUNDS.max - CAP_BOUNDS.min;
  const share = (amount - CAP_BOUNDS.min) / span;
  const atMost = Math.min(share, 1);
  return Math.max(atMost, 0);
}

export function capLabelOf(cap: SpendCap) {
  if (!cap.isCapped) {
    return 'No cap';
  }
  return `${formatWholeMoney(cap.amount)} a month`;
}

export function isCapReached(cap: SpendCap, spent: number) {
  if (!cap.isCapped) {
    return false;
  }
  return spent >= cap.amount;
}

export function sameCap(first: SpendCap, second: SpendCap) {
  const sameAmount = first.amount === second.amount;
  const sameSwitch = first.isCapped === second.isCapped;
  return sameAmount && sameSwitch;
}

export function daysLabelOf(days: number) {
  if (days === 1) {
    return '1 day';
  }
  return `${days} days`;
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { CheckIcon, LoaderCircleIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';

export type SaveStatus = 'idle' | 'saving' | 'saved';

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function labelOf(status: SaveStatus, idleLabel: string) {
  if (status === 'saving') {
    return 'Saving';
  }
  if (status === 'saved') {
    return 'Saved';
  }
  return idleLabel;
}

/** While saving, the pill keeps its full colour: it is working, not unavailable. */
function busyClassOf(isBusy: boolean) {
  if (isBusy) {
    return 'data-disabled:opacity-100 disabled:opacity-100';
  }
  return undefined;
}

function glyphOf(status: SaveStatus) {
  if (status === 'saving') {
    return {
      key: 'saving',
      icon: <LoaderCircleIcon className='animate-spin' />,
    };
  }
  if (status === 'saved') {
    return { key: 'saved', icon: <CheckIcon /> };
  }
  return null;
}

type SaveButtonProps = {
  status: SaveStatus;
  idleLabel: string;
  disabled?: boolean;
  onSave: () => void;
};

/** The label becomes its next state and the pill resizes to it. */
export function SaveButton({
  status,
  idleLabel,
  disabled = false,
  onSave,
}: SaveButtonProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);
  const label = labelOf(status, idleLabel);
  const glyph = glyphOf(status);
  const isBusy = status !== 'idle';
  const isDisabled = disabled || isBusy;
  const busyClass = busyClassOf(isBusy);

  return (
    <Button
      disabled={isDisabled}
      focusableWhenDisabled
      onClick={onSave}
      className={busyClass}
    >
      <AnimatedSize
        as='span'
        axis='width'
        contentClassName='relative flex items-center gap-1.5'
      >
        <AnimatePresence mode='popLayout' initial={false}>
          {glyph && (
            <motion.span
              key={glyph.key}
              variants={variants}
              initial='enter'
              animate='visible'
              exit='exit'
              transition={SWAP_TRANSITION}
              className='flex'
            >
              {glyph.icon}
            </motion.span>
          )}
        </AnimatePresence>
        <AnimatePresence mode='popLayout' initial={false}>
          <motion.span
            key={label}
            variants={variants}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={SWAP_TRANSITION}
          >
            {label}
          </motion.span>
        </AnimatePresence>
      </AnimatedSize>
    </Button>
  );
}

export type Meter = {
  id: string;
  label: string;
  used: number;
  included: number;
  unit: string;
  /** Price of each unit beyond the plan, or null when the plan stops at its limit. */
  overagePrice: number | null;
  /** How many decimals the figures of this meter keep. */
  decimals: number;
};

export const PLAN = {
  name: 'Growth plan',
